// @aufbau/bundler/steps/icons.js
// the icons a project uses ship as svg markup instead of coming from the iconify
// api. <aufbau-icon> asks AufbauIcon.provide() first, the api only for what it was
// not given, so the step writes one module that provides them and puts it into
// the pages ahead of the app:
//
//   icons: {
//     element : '@aufbau/elements/AufbauIcon.js',   // imported by that module, as the page resolves it
//     include : ['mdi:folder'],                      // ids no scan finds (built at runtime)
//     pages   : ['index.html'],
//     path    : '/_icons',
//   }
//
// the ids come from the staged files: every quoted `set:name` whose set is an
// iconify collection (the alias lists of @aufbau/icons and a project's own are
// such strings too). the svgs come from the @iconify-json/<set> packages on npm,
// built by @iconify/utils. an id that is not in its set is left out, the api
// still serves it at runtime.

import { existsSync } from 'node:fs';
import { mkdir, readFile, stat, writeFile } from 'node:fs/promises';
import { extname, join, relative } from 'node:path';
import { pathToFileURL } from 'node:url';
import { install, walk } from './../shared.js';

const SCANNED = new Set(['.html', '.js', '.json', '.mjs']);
const ID      = /["'`]([a-z0-9]+(?:-[a-z0-9]+)*):([a-z0-9]+(?:[-_][a-z0-9]+)*)["'`]/g;

async function icons ({ config, log, out, report }) {
  if (!config.icons) return;
  const {
    element = '@aufbau/elements/AufbauIcon.js',
    include = [],
    pages   = ['index.html'],
    path    = '/_icons',
  } = config.icons;

  // :::::: SCAN

  // vendored modules are minified third-party code, full of `a:b` strings
  const vendored   = (config.vendor?.path ?? '/_vendor').replace(/^\/+/, '') + '/';
  const candidates = new Set(include);
  for (const file of await walk(out)) {
    if (!SCANNED.has(extname(file)) || relative(out, file).startsWith(vendored)) continue;
    for (const [, set, name] of (await readFile(file, 'utf8')).matchAll(ID)) candidates.add(`${set}:${name}`);
  }

  // :::::: SETS

  const collections = await install('icons-collections', { '@iconify/collections': 'latest', '@iconify/utils': 'latest' }, log);
  const known  = JSON.parse(await readFile(join(collections.modules, '@iconify', 'collections', 'collections.json'), 'utf8'));
  const sets   = [...new Set([...candidates].map(id => id.split(':')[0]))].filter(set => known[set]).sort();
  if (!sets.length) return;

  const { modules, failed } = await install('icons', Object.fromEntries(sets.map(set => [`@iconify-json/${set}`, 'latest'])), log);
  const { getIconData, iconToHTML, iconToSVG, replaceIDs } = await import(pathToFileURL(join(collections.modules, '@iconify', 'utils', 'lib', 'index.js')));

  // :::::: BUILD

  const loaded = new Map;   // set -> icon set json
  const svgs   = {};
  for (const id of [...candidates].sort()) {
    const [set, name] = id.split(':');
    if (!known[set]) continue;
    if (!loaded.has(set)) {
      const file = join(modules, '@iconify-json', set, 'icons.json');
      loaded.set(set, existsSync(file) ? JSON.parse(await readFile(file, 'utf8')) : null);
    }
    const data = loaded.get(set) && getIconData(loaded.get(set), name);
    if (!data) continue;
    const { attributes, body } = iconToSVG(data);
    svgs[id] = iconToHTML(replaceIDs(body, `${set}-${name}-`), attributes);
  }

  // :::::: WRITE

  const target = join(out, path);
  await mkdir(target, { recursive: true });
  await writeFile(join(target, 'provide.js'), `// generated by @aufbau/bundler, the svgs of the icons this project uses\nimport AufbauIcon from '${element}';\nAufbauIcon.provide(${JSON.stringify(svgs)});\n`);

  // at the end of <head>: after whatever sets up the importmap, ahead of the app
  const tag = `<script type="module" src="${path}/provide.js"></script>`;
  for (const page of pages) {
    const file = join(out, page);
    if (existsSync(file)) await writeFile(file, (await readFile(file, 'utf8')).replace(/<\/head>/, `  ${tag}\n</head>`));
  }

  const bytes = (await stat(join(target, 'provide.js'))).size;
  log(`icons ${Object.keys(svgs).length} from ${sets.length} sets -> ${path}`);
  report('icons', [
    `local: ${Object.keys(svgs).length} icons from ${sets.join(', ')}, ${(bytes / 1024).toFixed(0)} kb`,
    ...failed.map(entry => `**not installed**: ${entry}`),
  ]);
}

export { icons };
export default icons;
